24	}
25	
26	type agentResponse struct {
27		Success   bool        `json:"success"`
28		Data      interface{} `json:"data,omitempty"`
29		Error     string      `json:"error,omitempty"`
30		Timestamp string      `json:"timestamp"`
31	}
32	
