164	func (dcs *DVECreationService) CreateDVENode(req *objects.DVECreationRequest) (*objects.DVECreationResponse, error) {
165		if req.StakeAmount < dcs.minStakeAmount {
166			return &objects.DVECreationResponse{
167				Success: false,
168				Error:   fmt.Sprintf("minimum stake amount is %d NRN", dcs.minStakeAmount),
169			}, nil
170		}
171	
172		if req.OwnerID == "" || req.OwnerAddress == "" {
173			return &objects.DVECreationResponse{
174				Success: false,
175				Error:   "owner ID and address are required",
176			}, nil
177		}
178	
179		dcs.mu.Lock()
180		dveNodeID := fmt.Sprintf("dve-%s", uuid.New().String()[:12])
181	
182		creation := &objects.DVECreation{
183			ID:             uuid.New().String(),
184			Name:           req.Name,
185			OwnerID:        req.OwnerID,
186			OwnerAddress:   req.OwnerAddress,
187			DVENodeID:      dveNodeID,
188			StakeAmount:    req.StakeAmount,
189			Status:         "pending",
190			TEEType:        req.TEEType,
191			TEEAttestation: req.TEEAttestation,
192			SessionKeyID:   generateSessionKeyID(),
193			Capabilities:   req.Capabilities,
194			ResourceLimits: req.ResourceLimits,
195			RegisteredAt:   time.Now(),
196			LastHeartbeat:  time.Now(),
197			UpdatedAt:      time.Now(),
198			Persistent:     req.Persistent,
199			GracePeriod:    dcs.gracePeriod,
200		}
201	
202		dcs.activeCreations[creation.ID] = creation
203		dcs.mu.Unlock()
204	
205		// Synchronously register the node in the DVE manager so it appears in the
206		// nodes list immediately — this is fast (in-memory + DB write, no I/O).
207		if dcs.dveManager != nil {
208			nodeReq := &objects.RegisterNodeRequest{
209				Name:         creation.Name,
210				TEEType:      creation.TEEType,
211				StakeAmount:  creation.StakeAmount,
212				Location:     "local-dve",
213				Capabilities: creation.Capabilities,
214			}
215			if node, err := dcs.dveManager.RegisterNode(nodeReq); err != nil {
216				log.Printf("[DVE Creation] Warning: Failed to register node in manager: %v", err)
217			} else {
218				dcs.mu.Lock()
219				creation.DVENodeID = node.ID
220				dcs.mu.Unlock()
221				log.Printf("[DVE Creation] Registered DVE node %s immediately for creation %s", node.ID, creation.ID)
222			}
223		}
224	
225		// Save initial pending record to database (no lock needed — buntdb is thread-safe)
226		if err := dcs.saveCreationToDatabase(creation); err != nil {
227			log.Printf("Warning: Failed to save DVE creation to database: %v", err)
228		}
229	
230		// Provision DVE asynchronously — container, agent, chain session
231		go dcs.provisionDVEInBackground(creation, req)
232	
233		return &objects.DVECreationResponse{
234			Success:     true,
235			DVECreation: creation,
236			Message:     "DVE node creation initiated — provisioning in background",
237		}, nil
238	}
239	
240	// provisionDVEInBackground runs in a goroutine. It does the slow work of
241	// container provisioning, DVE manager registration, KNIRVAGENT startup,
242	// and chain session establishment. Updates creation status to "active"
243	// on success or logs errors on failure.
244	func (dcs *DVECreationService) provisionDVEInBackground(creation *objects.DVECreation, req *objects.DVECreationRequest) {
245		// 1. Attempt on-chain registration (best-effort)
246		var registrationTxHash string
247		if dcs.chainClient != nil {
248			txHash, err := dcs.chainClient.RegisterDVENode(creation.DVENodeID, req.OwnerAddress, req.StakeAmount)
249			if err != nil {
250				log.Printf("[DVE Creation] Chain registration failed for %s: %v, proceeding with local provisioning", creation.ID, err)
251			} else {
252				registrationTxHash = txHash
253			}
254		}
255		creation.RegistrationTxHash = registrationTxHash
256	
257		// 2. Provision container if orchestrator is available
258		if dcs.containerOrchestrator != nil {
259			log.Printf("[DVE Creation] Provisioning container for creation %s", creation.ID)
260			container, err := dcs.containerOrchestrator.ProvisionContainer(creation.ID)
261			if err != nil {
262				log.Printf("[DVE Creation] Error provisioning container for %s: %v", creation.ID, err)
263				dcs.updateCreationStatus(creation.ID, "failed")
264				return
265			}
266	
267			// Preserve the manager node ID that was registered synchronously in
268			// CreateDVENode — container.ID is only used internally by the orchestrator
269			// and must not overwrite the stable DVENodeID that the nodes list uses.
270			managerNodeID := creation.DVENodeID
271			creation.SSHPublicKey = container.Spec.SSHPublicKey
272			creation.SSHPrivateKey = container.SSHKeys.PrivateKey
273			creation.SSHPort = container.Endpoints.SSHPort
274			creation.IPAddress = "localhost"
275			creation.ValidationPort = container.Endpoints.ValidationPort
276			creation.ErrorResPort = container.Endpoints.ErrorResPort
277	
278			// 3. Update the DVE node in the manager with container details so
279			// SSH/IP info is available for Access.  If no manager node was registered
280			// yet (no dveManager at creation time) fall back to registering now.
281			if dcs.dveManager != nil {
282				if managerNodeID != "" {
283					updates := map[string]interface{}{
284						"ip_address": creation.IPAddress,
285						"ssh_port":   creation.SSHPort,
286						"public_key": creation.SSHPublicKey,
287						"status":     "online",
288					}
289					if _, err := dcs.dveManager.UpdateNode(managerNodeID, updates); err != nil {
290						log.Printf("[DVE Creation] Warning: Failed to update DVE node details: %v", err)
291					} else {
292						log.Printf("[DVE Creation] Updated DVE node %s with container details", managerNodeID)
293					}
294				} else {
295					// Fallback: manager not wired at creation time — register now with full details
296					nodeReq := &objects.RegisterNodeRequest{
297						Name:         creation.Name,
298						TEEType:      creation.TEEType,
299						StakeAmount:  creation.StakeAmount,
300						Location:     "local-dve",
301						IPAddress:    creation.IPAddress,
302						SSHPort:      creation.SSHPort,
303						PublicKey:    creation.SSHPublicKey,
304						Capabilities: creation.Capabilities,
305					}
306					if node, err := dcs.dveManager.RegisterNode(nodeReq); err != nil {
307						log.Printf("[DVE Creation] Warning: Failed to register DVE node in tracker: %v", err)
308					} else {
309						creation.DVENodeID = node.ID
310						log.Printf("[DVE Creation] Registered DVE node %s (fallback)", node.ID)
311					}
312				}
313			}
314	
315			// 4. Auto-start KNIRVAGENT supervisor
316			if dcs.knirvagentManager != nil {
317				agentDVEID := creation.DVENodeID
318				startCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
319				defer cancel()
320				if err := dcs.knirvagentManager.StartAgent(startCtx, agentDVEID, 30*time.Second); err != nil {
321					log.Printf("[DVE Creation] Warning: Failed to start KNIRVAGENT supervisor for DVE %s: %v", agentDVEID, err)
322				} else {
323					creation.SupervisorAgentID = agentDVEID
324					log.Printf("[DVE Creation] KNIRVAGENT supervisor started for DVE %s (node %s)", creation.Name, agentDVEID)
325				}
326			}
327		}
328	
329		// 5. Establish chain session (best-effort)
330		chainSession, err := dcs.establishChainSession(creation)
331		if err != nil {
332			log.Printf("[DVE Creation] Warning: Failed to establish chain session: %v", err)
333		}
334	
335		// 6. Create DVE session
336		session := &objects.DVESession{
337			ID:             uuid.New().String(),
338			DVECreationID:  creation.ID,
339			DVENodeID:      creation.DVENodeID,
340			OwnerID:        creation.OwnerID,
341			SessionKey:     generateSessionKey(),
342			SessionKeyID:   creation.SessionKeyID,
343			TEEBinding:     req.TEEAttestation,
344			ChainSessionID: "",
345			Status:         "pending",
346			CreatedAt:      time.Now(),
347			ExpiresAt:      time.Now().Add(30 * time.Minute),
348		}
349	
350		if chainSession != nil {
351			session.ChainSessionID = chainSession.SessionID
352			session.Status = "active"
353			session.ExpiresAt = chainSession.ExpiresAt
354			session.PQCSignature = chainSession.PQCSignature
355		}
356	
357		now := time.Now()
358		creation.Status = "active"
359		creation.ChainSessionID = session.ChainSessionID
360		creation.ActivatedAt = &now
361		creation.UpdatedAt = now
362	
363		// 7. Update in-memory maps and persist
364		dcs.mu.Lock()
365		dcs.activeCreations[creation.ID] = creation
366		dcs.activeSessions[session.ID] = session
367		dcs.mu.Unlock()
368	
369		if err := dcs.saveCreationToDatabase(creation); err != nil {
370			log.Printf("[DVE Creation] Warning: Failed to save updated DVE creation: %v", err)
371		}
372		if err := dcs.saveSessionToDatabase(session); err != nil {
373			log.Printf("[DVE Creation] Warning: Failed to save DVE session: %v", err)
374		}
375	
376		log.Printf("[DVE Creation] DVE %s (%s) fully provisioned and active", creation.Name, creation.ID)
377	}
