379	// updateCreationStatus sets the status of an in-memory creation and persists it.
380	// Must be called from the background goroutine (not while holding the mutex).
381	func (dcs *DVECreationService) updateCreationStatus(id, status string) {
382		dcs.mu.Lock()
383		creation, exists := dcs.activeCreations[id]
384		if exists {
385			creation.Status = status
386			creation.UpdatedAt = time.Now()
387		}
388		dcs.mu.Unlock()
389	
390		if exists {
391			if err := dcs.saveCreationToDatabase(creation); err != nil {
392				log.Printf("Warning: Failed to save status update for creation %s: %v", id, err)
393			}
394		}
395	}
