466			return tx.Ascend("", func(key, value string) bool {
467				if len(key) > 13 && key[:13] == "dve_creation:" {
468					var creation objects.DVECreation
469					if err := json.Unmarshal([]byte(value), &creation); err == nil {
470						if creation.OwnerID == userID {
471							found := false
472							for _, c := range userCreations {
473								if c.ID == creation.ID {
474									found = true
475									break
476								}
477							}
478							if !found {
479								userCreations = append(userCreations, &creation)
480							}
481						}
482					}
483				}
484				return true
485			})
486		})
487	
488		if err != nil {
489			return nil, fmt.Errorf("failed to query user DVE creations: %w", err)
490		}
491	
492		return userCreations, nil
493	}
