617	func (dcs *DVECreationService) DecommissionDVENode(creationID, ownerID string) error {
618		dcs.mu.Lock()
619		defer dcs.mu.Unlock()
620	
621		creation, exists := dcs.activeCreations[creationID]
622		if !exists {
623			return fmt.Errorf("DVE creation not found: %s", creationID)
624		}
625	
626		if creation.OwnerID != ownerID {
627			return fmt.Errorf("unauthorized: not the owner of this DVE")
628		}
629	
630		creation.Status = "decommissioned"
631		creation.UpdatedAt = time.Now()
632	
633		for sessionID, session := range dcs.activeSessions {
634			if session.DVECreationID == creationID {
635				session.Status = "revoked"
636				dcs.saveSessionToDatabase(session)
637				delete(dcs.activeSessions, sessionID)
638			}
639		}
640	
641		if err := dcs.saveCreationToDatabase(creation); err != nil {
642			return fmt.Errorf("failed to save decommissioned DVE: %w", err)
643		}
644	
645		delete(dcs.activeCreations, creationID)
646	
647		return nil
648	}
