709	func (dcs *DVECreationService) loadFromDatabase() error {
710		if dcs.db == nil {
711			return fmt.Errorf("database not initialized")
712		}
713	
714		err := dcs.db.GetObjectsByPrefix("dve_creation:", func(key string, value []byte) bool {
715			var creation objects.DVECreation
716			if err := json.Unmarshal(value, &creation); err == nil {
717				if creation.Status == "active" || creation.Status == "pending" {
718					dcs.activeCreations[creation.ID] = &creation
719				}
720			}
721			return true
722		})
723		if err != nil {
724			return err
725		}
726	
727		return dcs.db.GetObjectsByPrefix("dve_session:", func(key string, value []byte) bool {
728			var session objects.DVESession
729			if err := json.Unmarshal(value, &session); err == nil {
730				if session.Status == "active" {
731					dcs.activeSessions[session.ID] = &session
732				}
733			}
734			return true
735		})
736	}
