738	func (dcs *DVECreationService) saveToDatabase() error {
739		if dcs.db == nil {
740			return fmt.Errorf("database not initialized")
741		}
742	
743		return dcs.db.Transaction(func(tx *buntdb.Tx) error {
744			for _, creation := range dcs.activeCreations {
745				if data, err := json.Marshal(creation); err == nil {
746					tx.Set("dve_creation:"+creation.ID, string(data), nil)
747				}
748			}
749			for _, session := range dcs.activeSessions {
750				if data, err := json.Marshal(session); err == nil {
751					tx.Set("dve_session:"+session.ID, string(data), nil)
752				}
753			}
754			return nil
755		})
756	}
