763		data, err := json.Marshal(creation)
764		if err != nil {
765			return fmt.Errorf("failed to marshal creation: %w", err)
766		}
767	
768		return dcs.db.Transaction(func(tx *buntdb.Tx) error {
769			_, _, err := tx.Set("dve_creation:"+creation.ID, string(data), nil)
770			return err
771		})
772	}
