774	func (dcs *DVECreationService) saveSessionToDatabase(session *objects.DVESession) error {
775		if dcs.db == nil {
776			return fmt.Errorf("database not initialized")
777		}
778	
779		data, err := json.Marshal(session)
780		if err != nil {
781			return fmt.Errorf("failed to marshal session: %w", err)
782		}
783	
784		return dcs.db.Transaction(func(tx *buntdb.Tx) error {
785			_, _, err := tx.Set("dve_session:"+session.ID, string(data), nil)
786			return err
787		})
788	}
789	
790	func (dcs *DVECreationService) countActiveCreations() int64 {
791		count := int64(0)
792		now := time.Now()
793		for _, creation := range dcs.activeCreations {
794			if creation.Status == "active" && now.Sub(creation.LastHeartbeat) < 10*time.Minute {
795				count++
796			}
797		}
798		return count
799	}
800	
801	func (dcs *DVECreationService) countActiveSessions() int64 {
802		count := int64(0)
803		now := time.Now()
804		for _, session := range dcs.activeSessions {
805			if session.Status == "active" && now.Before(session.ExpiresAt) {
806				count++
807			}
808		}
809		return count
810	}
811	
812	func (dcs *DVECreationService) cleanupRoutine() {
813		ticker := time.NewTicker(dcs.cleanupInterval)
814		defer ticker.Stop()
815	
816		for range ticker.C {
817			if !dcs.running {
818				return
819			}
820			dcs.cleanupExpiredSessions()
821		}
822	}
823	
824	func (dcs *DVECreationService) cleanupExpiredSessions() {
825		dcs.mu.Lock()
826		defer dcs.mu.Unlock()
827	
828		now := time.Now()
829		expiredCount := 0
830	
831		for id, session := range dcs.activeSessions {
832			if now.After(session.ExpiresAt) {
833				session.Status = "expired"
834				dcs.saveSessionToDatabase(session)
835				delete(dcs.activeSessions, id)
836				expiredCount++
837			}
838		}
839	
840		if expiredCount > 0 {
841			log.Printf("Cleaned up %d expired DVE sessions", expiredCount)
842		}
843	}
844	
845	func (dcs *DVECreationService) sessionValidationRoutine() {
846		ticker := time.NewTicker(1 * time.Minute)
847		defer ticker.Stop()
848	
849		for range ticker.C {
850			if !dcs.running {
851				return
852			}
853			dcs.validateChainSessions()
854		}
855	}
856	
857	func (dcs *DVECreationService) validateChainSessions() {
858		dcs.mu.RLock()
859		sessions := make([]*objects.DVESession, 0, len(dcs.activeSessions))
860		for _, session := range dcs.activeSessions {
861			if session.Status == "active" {
862				sessions = append(sessions, session)
863			}
864		}
865		dcs.mu.RUnlock()
866	
867		if dcs.chainClient == nil {
868			return
869		}
870	
871		for _, session := range sessions {
872			_, err := dcs.chainClient.ValidateSession(session.ChainSessionID)
873			if err != nil {
874				log.Printf("Session validation failed for %s: %v", session.ChainSessionID, err)
875				dcs.mu.Lock()
876				session.Status = "expired"
877				dcs.saveSessionToDatabase(session)
878				delete(dcs.activeSessions, session.ID)
879				dcs.mu.Unlock()
880			}
881		}
882	}
883	
884	func generateSessionKey() []byte {
885		key := make([]byte, 32)
886		rand.Read(key)
887		return key
888	}
889	
890	func generateSessionKeyID() string {
891		hash := sha256.Sum256([]byte(uuid.New().String()))
892		return base64.URLEncoding.EncodeToString(hash[:])[:16]
893	}
