18	type KNIRVSHELLService struct {
19		sessions   map[string]*TerminalSession
20		sessionMu  sync.RWMutex
21		binaryPath string
22	}
23	
24	type TerminalSession struct {
25		ID        string       `json:"id"`
26		NodeID    string       `json:"node_id,omitempty"`
27		UserID    string       `json:"user_id,omitempty"`
28		Username  string       `json:"username,omitempty"`
29		Command   string       `json:"command,omitempty"`
30		Status    string       `json:"status"`
31		StartTime time.Time    `json:"start_time"`
32		EndTime   *time.Time   `json:"end_time,omitempty"`
33		Output    []string     `json:"output,omitempty"`
34		ExitCode  int          `json:"exit_code"`
35		Process   *exec.Cmd    `json:"-"`
36		stdin     io.WriteCloser `json:"-"`
37		stdout    io.ReadCloser  `json:"-"`
38		stderr    io.ReadCloser  `json:"-"`
39	}
