159	func (s *KNIRVSHELLService) ExecuteCommand(ctx context.Context, req *CommandRequest) (*CommandResult, error) {
160		sessionID := uuid.New().String()[:12]
161	
162		session := &TerminalSession{
163			ID:        sessionID,
164			NodeID:    req.NodeID,
165			UserID:    req.UserID,
166			Username:  req.Username,
167			Command:   req.Command,
168			Status:    "running",
169			StartTime: time.Now(),
170			Output:    []string{},
171		}
172	
173		s.sessionMu.Lock()
174		s.sessions[sessionID] = session
175		s.sessionMu.Unlock()
176	
177		args := []string{}
178		if req.NodeID != "" {
179			args = append(args, "--node", req.NodeID)
180		}
181		args = append(args, req.Args...)
182		args = append(args, "--", req.Command)
183	
184		cmd := exec.CommandContext(ctx, s.binaryPath, args...)
185	
186		if req.Env != nil {
187			for k, v := range req.Env {
188				cmd.Env = append(cmd.Env, fmt.Sprintf("%s=%s", k, v))
189			}
190		}
191	
192		stdin, err := cmd.StdinPipe()
193		if err != nil {
194			return nil, fmt.Errorf("failed to create stdin pipe: %w", err)
195		}
196		session.stdin = stdin
197	
198		stdout, err := cmd.StdoutPipe()
199		if err != nil {
200			return nil, fmt.Errorf("failed to create stdout pipe: %w", err)
201		}
202		session.stdout = stdout
203	
204		stderr, err := cmd.StderrPipe()
205		if err != nil {
206			return nil, fmt.Errorf("failed to create stderr pipe: %w", err)
207		}
208		session.stderr = stderr
209	
210		session.Process = cmd
211	
212		if err := cmd.Start(); err != nil {
213			session.Status = "failed"
214			return nil, fmt.Errorf("failed to start command: %w", err)
215		}
216	
217		go s.streamOutput(session, stdout, "stdout")
218		go s.streamOutput(session, stderr, "stderr")
219	
220		go func() {
221			err := cmd.Wait()
222			now := time.Now()
223			session.EndTime = &now
224			if err != nil {
225				session.Status = "failed"
226				if exitErr, ok := err.(*exec.ExitError); ok {
227					session.ExitCode = exitErr.ExitCode()
228				} else {
229					session.ExitCode = 1
230				}
231			} else {
232				session.Status = "completed"
233				session.ExitCode = 0
234			}
235		}()
236	
237		return &CommandResult{
238			SessionID: sessionID,
239			Command:   req.Command,
240			Status:    "running",
241			StartTime: session.StartTime.Format(time.RFC3339),
242		}, nil
243	}
