245	func (s *KNIRVSHELLService) streamOutput(session *TerminalSession, reader io.Reader, streamType string) {
246		buf := make([]byte, 4096)
247		for {
248			n, err := reader.Read(buf)
249			if n > 0 {
250				output := string(buf[:n])
251				session.Output = append(session.Output, output)
252				log.Printf("[%s] %s", streamType, output)
253			}
254			if err != nil {
255				if err != io.EOF {
256					log.Printf("Error reading %s for session %s: %v", streamType, session.ID, err)
257				}
258				break
259			}
260		}
261	}
