493	func ResolveBinaryPath() (string, error) {
494		if p := os.Getenv("KNIRV_SHELL_PATH"); p != "" {
495			if _, err := os.Stat(p); err == nil {
496				return p, nil
497			}
498		}
499	
500		dir := os.Getenv("KNIRV_SHELL_BINARY_DIR")
501		if dir == "" {
502			xdgDataHome := os.Getenv("XDG_DATA_HOME")
503			if xdgDataHome != "" {
504				dir = filepath.Join(xdgDataHome, "knirvserver", "bin")
505			} else {
506				homeDir, err := os.UserHomeDir()
507				if err != nil {
508					return "", fmt.Errorf("failed to resolve home directory: %w", err)
509				}
510				dir = filepath.Join(homeDir, ".local", "share", "knirvserver", "bin")
511			}
512		}
513	
514		binPath := filepath.Join(dir, "knirvshell")
515		if _, err := os.Stat(binPath); err == nil {
516			return binPath, nil
517		}
518	
519		return ExtractEmbeddedBinary(dir)
520	}
